void TypeScriptUpstreamScannerFixtures()
{
    size_t token_count = 0;
    size_t case_count = 0;
    for (const auto& fixture : fixtures)
    {
        const mn::language::Text text(fixture.text);
        mn::typescript::Scanner scanner(text);
        for (size_t i = 0; i < fixture.count; ++i)
        {
            const auto actual = scanner.scan();
            const auto& expected = fixture.tokens[i];
            if (actual.kind != expected.kind || actual.start != expected.start || actual.end != expected.end ||
                actual.flags != expected.flags || (expected.value && actual.value != std::string_view(expected.value, expected.value_length)))
                throw std::runtime_error("TypeScript upstream scanner fixture " + std::to_string(case_count) +
                    ", token " + std::to_string(i) + " differs from the pinned upstream oracle");
            ++token_count;
        }
        if (scanner.kind != mn::typescript::sk::EndOfFileToken)
            throw std::runtime_error("TypeScript fixture did not terminate at EOF");
        ++case_count;
    }
    std::cout << "TypeScript upstream scanner: " << case_count << " fixtures, " << token_count
              << " token records PASS (C++; no Node/Python runtime)\n";
}
